source/plain_r4:
/* S2: covenant tree node, plain form. Output i (i = 0..r-1) must carry the
 * pinned explicit asset, the pinned explicit amount, and the pinned script
 * (compared by SHA256 of the scriptPubKey). No signature, no witness.
 * Nothing else in the transaction is constrained. */
fn check(i: u32, value: u64, spk_hash: u256) {
    let (a, v): (Asset1, Amount1) = unwrap(jet::output_amount(i));
    match a {
        Left(c: (u1, u256)) => panic!(),
        Right(id: ExplicitAsset) => assert!(jet::eq_256(id, param::ASSET)),
    };
    match v {
        Left(c: (u1, u256)) => panic!(),
        Right(x: u64) => assert!(jet::eq_64(x, value)),
    };
    assert!(jet::eq_256(unwrap(jet::output_script_hash(i)), spk_hash));
}

fn main() {
    check(0, param::V0, param::S0);
    check(1, param::V1, param::S1);
    check(2, param::V2, param::S2);
    check(3, param::V3, param::S3);
}

source/compact_r4:
/* S2: covenant tree node, compact form. jet::output_hash(i) is the SHA256 of
 * output i's (asset, amount, nonce, script hash, range proof hash) with their
 * confidentiality prefixes, so one jet pins the whole output. The r output
 * hashes are folded into one SHA256 and compared with ONE constant.
 * No signature, no witness; outputs r.. and all inputs are unconstrained. */
fn main() {
    let ctx: Ctx8 = jet::sha_256_ctx_8_init();
    let ctx: Ctx8 = jet::sha_256_ctx_8_add_32(ctx, unwrap(jet::output_hash(0)));
    let ctx: Ctx8 = jet::sha_256_ctx_8_add_32(ctx, unwrap(jet::output_hash(1)));
    let ctx: Ctx8 = jet::sha_256_ctx_8_add_32(ctx, unwrap(jet::output_hash(2)));
    let ctx: Ctx8 = jet::sha_256_ctx_8_add_32(ctx, unwrap(jet::output_hash(3)));
    assert!(jet::eq_256(jet::sha_256_ctx_8_finalize(ctx), param::H));
}

source/chain_r4:
/* S2: covenant tree node, smallest form found. As node_compact, but the r
 * output hashes are chained through the raw SHA256 compression function, two
 * per block, starting from the SHA256 IV. There is no length padding, which is
 * sound here because r is fixed by the program (the chain is a fixed-arity
 * Merkle-Damgard hash). Saves the three context jets of the streaming form. */
fn main() {
    let h: u256 = jet::sha_256_iv();
    let h: u256 = jet::sha_256_block(h, unwrap(jet::output_hash(0)), unwrap(jet::output_hash(1)));
    let h: u256 = jet::sha_256_block(h, unwrap(jet::output_hash(2)), unwrap(jet::output_hash(3)));
    assert!(jet::eq_256(h, param::H));
}
